-- public.pair_them(p_world uuid, p_dam integer, p_sire integer, p_husbandry double precision, p_uid uuid, p_sex text)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.pair_them(p_world uuid, p_dam integer, p_sire integer, p_husbandry double precision, p_uid uuid DEFAULT NULL::uuid, p_sex text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
/*
 * `v_care`, not `care`. The eighth time this class has bitten: a local called
 * `care` inside an `update creature` is not a local, it is the column, and
 * Postgres says "ambiguous" if you are lucky. Alias every table, prefix every
 * local — the rule has not changed and neither has the mistake.
 */
declare dam creature; sire creature; v_care double precision; v_bred jsonb; v_twin jsonb;
        v_keep double precision; v_up double precision; v_sex text; v_rest double precision; v_copy text[]; v_m creature; v_fresh double precision; v_mutate double precision;
begin
  select * into dam from creature where world_id = p_world and id = p_dam;
  select * into sire from creature where world_id = p_world and id = p_sire;
  v_care := (dam.care + sire.care) / 2;
  /*
   * What the breeder's perks put into it, read off whoever put them together:
   * more of the pair and more of it a tier better (True Blood, Bred Up), the
   * sex they asked for (Choose the Sex) or even odds, now and then a second
   * young bred for itself (Twins), carried for less of the time (Quick
   * Gestation), and both ready again sooner (Short Rest).
   */
  v_keep := pk(p_world, p_uid, 'breed:inherit', 0);
  -- And more for Love's Good Stock.
  v_up := pk(p_world, p_uid, 'breed:upgrade', 0) + path_fx(p_world, p_uid, 'up', 0);
  v_sex := case when p_sex in ('male', 'female') and pk(p_world, p_uid, 'breed:sex', 0) > 0 then p_sex end;
  v_copy := mirror_copy(dam, sire);
  -- And what the pair's blood does to the draw (`pair_fresh`, `pair_mutate`).
  v_fresh := pair_fresh(dam, sire);
  v_mutate := pair_mutate(dam, sire);
  v_bred := breed_traits(sire.traits, dam.traits, p_husbandry, v_care, v_keep, v_up, v_copy, v_fresh, v_mutate);
  if random() < twin_chance(pk(p_world, p_uid, 'breed:twins', 0), dam) then
    v_twin := breed_traits(sire.traits, dam.traits, p_husbandry, v_care, v_keep, v_up, v_copy, v_fresh, v_mutate);
    v_twin := jsonb_build_object('traits', v_twin->'traits', 'from', v_twin->'from',
      'line', bred_line(array(select jsonb_array_elements_text(v_twin->'traits')),
                        dam.traits, dam.pedigree->'line', sire.traits, sire.pedigree->'line'),
      'sex', coalesce(v_sex, case when random() < 0.5 then 'male' else 'female' end));
  end if;
  v_rest := breed_rest() * (1 - pk(p_world, p_uid, 'breed:rest', 1));
  -- The sire is written down now, by id and by name, with where each trait
  -- came from: he need not be about when the hour comes.
  update creature set
      unborn = jsonb_build_object(
        'traits', v_bred->'traits',
        'sex', coalesce(v_sex, case when random() < 0.5 then 'male' else 'female' end),
        'sire', jsonb_build_object('id', sire.id, 'name', sire.name),
        'from', v_bred->'from',
        'line', bred_line(array(select jsonb_array_elements_text(v_bred->'traits')),
                          dam.traits, dam.pedigree->'line', sire.traits, sire.pedigree->'line'))
        -- And its parents' forms, at `form_pass` for each that has one (`bred_form`).
        || (select jsonb_strip_nulls(jsonb_build_object('formColour', case when f.form_colour then true end, 'formSize', f.form_size))
              from bred_form(dam.form_colour, dam.form_size, sire.form_colour, sire.form_size, random(), random()) f)
        || case when v_twin is null then '{}'::jsonb else jsonb_build_object('twin', v_twin
             || (select jsonb_strip_nulls(jsonb_build_object('formColour', case when f.form_colour then true end, 'formSize', f.form_size))
                   from bred_form(dam.form_colour, dam.form_size, sire.form_colour, sire.form_size, random(), random()) f)) end,
      due = now() + make_interval(secs => gestation_of(pk(p_world, p_uid, 'breed:gestation', 1), dam)),
      bred_at = now() - make_interval(secs => v_rest)
    where world_id = p_world and id = p_dam;
  update creature set bred_at = now() - make_interval(secs => v_rest) where world_id = p_world and id = p_sire;
  -- And each mirror's mark used up, and said, the dam's first.
  for v_m in select * from creature m where m.world_id = p_world and m.id in (p_dam, p_sire) and mirrored(m)
              order by (m.id <> p_dam) loop
    update creature set boosts = nullif(boosts - 'mirror', '{}'::jsonb) where world_id = p_world and id = v_m.id;
    if mirror_trait(v_m.traits) is not null then
      perform journal_note(p_world, p_uid, 'mirrored');
      perform wtell(p_world, p_uid, 'Bronze mirror: ' || mirror_names(mirror_trait(v_m.traits)) || ' from ' || v_m.name
        || ' to the young. Mark used up.', 'event');
    end if;
  end loop;
end $function$
